const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/checklist/users',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[vendor_id]': 'SOME_INTEGER_VALUE',
    'filters[potential_assignee]': 'SOME_BOOLEAN_VALUE',
    'filters[potential_distribution_member]': 'SOME_BOOLEAN_VALUE',
    'filters[potential_point_of_contact]': 'SOME_BOOLEAN_VALUE',
    'filters[potential_signatory]': 'SOME_BOOLEAN_VALUE',
    'filters[inspection_id]': 'SOME_INTEGER_VALUE',
    sort: 'SOME_STRING_VALUE',
    view: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/checklist/users?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bvendor_id%5D=SOME_INTEGER_VALUE&filters%5Bpotential_assignee%5D=SOME_BOOLEAN_VALUE&filters%5Bpotential_distribution_member%5D=SOME_BOOLEAN_VALUE&filters%5Bpotential_point_of_contact%5D=SOME_BOOLEAN_VALUE&filters%5Bpotential_signatory%5D=SOME_BOOLEAN_VALUE&filters%5Binspection_id%5D=SOME_INTEGER_VALUE&sort=SOME_STRING_VALUE&view=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
